window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f9891d5a240cdbc4"]={"versions": [{"id": "FIG-f9891d5a240cdbc4", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Blockdiagramm zur Einordnung der Wireless-Ethernet-Module in die AUTOSAR-Basissoftwarearchitektur. Das Diagramm gliedert den Wireless-Ethernet-Stack vertikal in zwei Hauptdomänen: den oberen Softwarebereich („Software“) und den darunterliegenden Hardwarebereich („Hardware“), welcher an das physikalische Übertragungsmedium („Wireless Ethernet Physical Medium“) ankoppelt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Software-Ebene umfasst:</p>\n<ul class=\"fig-list\"><li><strong>Ethernet Interface</strong>: Übergreifendes Kommunikations-Interface der oberen BSW-Ebene.\n</li><li><strong>Wireless Ethernet Driver</strong> (hervorgehoben): BSW-Treiberbaustein für die Steuerung der Sende- und Empfangsoperationen sowie Datenübertragung.\n</li><li><strong>Wireless Ethernet Transceiver Driver</strong> (hervorgehoben): BSW-Treiberbaustein für die Konfiguration und Zustandssteuerung der Transceiver-Hardware.\n</li></ul>\n<p class=\"fig-p\">Die Hardware-Ebene umfasst:</p>\n<ul class=\"fig-list\"><li><strong>Radio 1 Tx Queue’s</strong> und <strong>Radio 2 Tx Queue’s</strong>: Hardwarebasierte Sendewarteschlangen für zwei separate Funkschnittstellen/Radios, direkt zugeordnet zum <em>Wireless Ethernet Driver</em>.\n</li><li><strong>Radio 1 Config</strong> und <strong>Radio 2 Config</strong>: Hardware-Konfigurations- und Kontrollregister bzw. Steuereinheiten für beide Radios, direkt zugeordnet zum <em>Wireless Ethernet Transceiver Driver</em>.\n</li><li><strong>Wireless Ethernet Physical Medium</strong>: Das gemeinsame physikalische Funkübertragungsmedium als unterste Hardwarebasis.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architekturschema ohne explizite Interaktionssequenzen oder Kontrollflusspfeile. Die räumliche Anordnung visualisiert folgende funktionale Kopplungen:</p>\n<ul class=\"fig-list\"><li>Das <em>Ethernet Interface</em> adressiert abwärtsgerichtet sowohl den <em>Wireless Ethernet Driver</em> als auch den <em>Wireless Ethernet Transceiver Driver</em>.\n</li><li>Der <em>Wireless Ethernet Driver</em> bedient datenseitig die Sendewarteschlangen beider Funkkanäle (<em>Radio 1 Tx Queue’s</em>, <em>Radio 2 Tx Queue’s</em>).\n</li><li>Der <em>Wireless Ethernet Transceiver Driver</em> greift steuerungs- und konfigurationsseitig auf die Konfigurationsblöcke beider Funkmodule zu (<em>Radio 1 Config</em>, <em>Radio 2 Config</em>).\n</li><li>Beide Radio-Hardwareblöcke interagieren auf physikalischer Ebene mit dem <em>Wireless Ethernet Physical Medium</em>.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Trennung zwischen Nutzdatenpfad (<em>Wireless Ethernet Driver</em>) und Steuerungs-/Konfigurationspfad (<em>Wireless Ethernet Transceiver Driver</em>). Implementierer müssen beachten, dass die Spezifikation eine Multi-Radio-Architektur (hier exemplarisch für mindestens zwei Radios: Radio 1 und Radio 2) mit separaten Hardware-Tx-Warteschlangen und separaten Konfigurationsbereichen vorsieht, die von den jeweiligen Treiberinstanzen parallel bzw. getrennt verwaltet werden müssen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a3c9d73f0113912d", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Blockdiagramm zur Einordnung der Wireless-Ethernet-Module in die AUTOSAR-Basissoftwarearchitektur. Das Diagramm gliedert den Wireless-Ethernet-Stack vertikal in zwei Hauptdomänen: den oberen Softwarebereich („Software“) und den darunterliegenden Hardwarebereich („Hardware“), welcher an das physikalische Übertragungsmedium („Wireless Ethernet Physical Medium“) ankoppelt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Software-Ebene umfasst:</p>\n<ul class=\"fig-list\"><li><strong>Ethernet Interface</strong>: Übergreifendes Kommunikations-Interface der oberen BSW-Ebene.\n</li><li><strong>Wireless Ethernet Driver</strong> (hervorgehoben): BSW-Treiberbaustein für die Steuerung der Sende- und Empfangsoperationen sowie Datenübertragung.\n</li><li><strong>Wireless Ethernet Transceiver Driver</strong> (hervorgehoben): BSW-Treiberbaustein für die Konfiguration und Zustandssteuerung der Transceiver-Hardware.\n</li></ul>\n<p class=\"fig-p\">Die Hardware-Ebene umfasst:</p>\n<ul class=\"fig-list\"><li><strong>Radio 1 Tx Queue’s</strong> und <strong>Radio 2 Tx Queue’s</strong>: Hardwarebasierte Sendewarteschlangen für zwei separate Funkschnittstellen/Radios, direkt zugeordnet zum <em>Wireless Ethernet Driver</em>.\n</li><li><strong>Radio 1 Config</strong> und <strong>Radio 2 Config</strong>: Hardware-Konfigurations- und Kontrollregister bzw. Steuereinheiten für beide Radios, direkt zugeordnet zum <em>Wireless Ethernet Transceiver Driver</em>.\n</li><li><strong>Wireless Ethernet Physical Medium</strong>: Das gemeinsame physikalische Funkübertragungsmedium als unterste Hardwarebasis.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architekturschema ohne explizite Interaktionssequenzen oder Kontrollflusspfeile. Die räumliche Anordnung visualisiert folgende funktionale Kopplungen:</p>\n<ul class=\"fig-list\"><li>Das <em>Ethernet Interface</em> adressiert abwärtsgerichtet sowohl den <em>Wireless Ethernet Driver</em> als auch den <em>Wireless Ethernet Transceiver Driver</em>.\n</li><li>Der <em>Wireless Ethernet Driver</em> bedient datenseitig die Sendewarteschlangen beider Funkkanäle (<em>Radio 1 Tx Queue’s</em>, <em>Radio 2 Tx Queue’s</em>).\n</li><li>Der <em>Wireless Ethernet Transceiver Driver</em> greift steuerungs- und konfigurationsseitig auf die Konfigurationsblöcke beider Funkmodule zu (<em>Radio 1 Config</em>, <em>Radio 2 Config</em>).\n</li><li>Beide Radio-Hardwareblöcke interagieren auf physikalischer Ebene mit dem <em>Wireless Ethernet Physical Medium</em>.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Trennung zwischen Nutzdatenpfad (<em>Wireless Ethernet Driver</em>) und Steuerungs-/Konfigurationspfad (<em>Wireless Ethernet Transceiver Driver</em>). Implementierer müssen beachten, dass die Spezifikation eine Multi-Radio-Architektur (hier exemplarisch für mindestens zwei Radios: Radio 1 und Radio 2) mit separaten Hardware-Tx-Warteschlangen und separaten Konfigurationsbereichen vorsieht, die von den jeweiligen Treiberinstanzen parallel bzw. getrennt verwaltet werden müssen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-f9891d5a240cdbc4", "to": "FIG-a3c9d73f0113912d", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
